import datetime

class Task:
    VALID_PRIORITIES = range(1, 6)

    def __init__(self, task_id, name, priority=3, due_date=None):
        self.task_id = task_id
        self.name = name
        self.priority = priority
        self.due_date = due_date
        self.complete = False
        self.tags = []
        self.created_at = datetime.datetime.now()

    @property
    def priority(self):
        return self._priority

    @priority.setter
    def priority(self, value):
        if value not in self.VALID_PRIORITIES:
            raise ValueError(f"Priority must be 1-5, got {value}")
        self._priority = value

    def mark_complete(self):
        if self.complete:
            raise RuntimeError("Task is already complete")
        self.complete = True

    def add_tag(self, tag):
        normalized = tag.strip().lower()
        if normalized and normalized not in self.tags:
            self.tags.append(normalized)

    def remove_tag(self, tag):
        normalized = tag.strip().lower()
        if normalized in self.tags:
            self.tags.remove(normalized)

    def is_overdue(self):
        if self.complete or self.due_date is None:
            return False
        return datetime.datetime.now() > self.due_date

    def __repr__(self):
        status = "done" if self.complete else "pending"
        return f"Task({self.task_id}, '{self.name}', {status})"
